fn to_lowercase(s: &Vec<char>) -> Vec<char> {
    // Pre-allocate the result vector with the same length as the input
    let mut result = Vec::with_capacity(s.len());
    
    for &c in s.iter() {
        // Check if c is an ASCII uppercase letter
        if c >= 'A' && c <= 'Z' {
            // Convert to lowercase by adding 32 to the ASCII code point
            let lower = ((c as u8) + 32) as char;
            result.push(lower);
        } else {
            // Otherwise keep the character unchanged
            result.push(c);
        }
    }
    
    result
}

